import{_ as o,o as t,c as r,a2 as d}from"./chunks/framework.DTwTvi8b.js";const m=JSON.parse('{"title":"0029 从卡片开始的需求：需求会话代替人，卡片描述代替对话","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"reference/adr/0029-requirements-from-cards.md","filePath":"reference/adr/0029-requirements-from-cards.md","lastUpdated":null}'),c={name:"reference/adr/0029-requirements-from-cards.md"};function a(i,e,s,l,n,u){return t(),r("div",null,[...e[0]||(e[0]=[d('<div><h1 id="_0029-从卡片开始的需求-需求会话代替人-卡片描述代替对话" tabindex="-1">0029 从卡片开始的需求：需求会话代替人，卡片描述代替对话 <a class="header-anchor" href="#_0029-从卡片开始的需求-需求会话代替人-卡片描述代替对话" aria-label="Permalink to &quot;0029 从卡片开始的需求：需求会话代替人，卡片描述代替对话&quot;">​</a></h1><ul><li>状态：已采纳（1.10.0-beta.2；建在 <a href="./0028-external-integrations">0028</a> 的外部系统对接之上）</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>团队希望需求不必有人坐在 Paseo 对话前发起：需求方在需求管理系统（ALM）中写好一张卡片、标题加上约定的标识，就由一台共享的研发机器接手，整理需求、请需求方确认、开发、提测，结果回到卡片上。人只在确认需求、确认方案、验收这几个点介入（&quot;软件工厂&quot;）。</p><p>约束：</p><ul><li>ALM 不支持评论，状态只有新建、开发中、待测试等，没有&quot;待补充&quot;&quot;待确认&quot;。</li><li>现有规则：步骤 agent 挂在发起需求的对话下，对话的工作目录不变；流水线只在本地提交。</li><li>卡片描述可能已经是一份完整的需求文档，也可能只有一句话；内容来自需求方，不能当作给 agent 的指令。</li></ul><p>另评估过 Paseo Hub：它的事件来源（GitHub、Slack、Discord、Linear）是编译在 Hub 代码里的，没有插件或通用 webhook；可用的扩展口只有开放 API 的 <code>manual.run</code> 和定时触发。代码在内部 GitLab、IM 是内部工具、Hub 只能内网自建，所以不用 Hub 接单；以后一台机器不够用时，再用内网 Hub 的 <code>manual.run</code> 把需求派到多台机器。</p><h2 id="决定" tabindex="-1">决定 <a class="header-anchor" href="#决定" aria-label="Permalink to &quot;决定&quot;">​</a></h2><ul><li><strong>需求会话代替人</strong>：<code>req start --from &lt;系统&gt;:&lt;卡号&gt;</code> 读卡片、建功能目录（<code>docs/features/&lt;日期&gt;-&lt;卡号简称&gt;/</code>），然后在 Paseo 中为这个需求建一个顶层 agent（需求会话），工作目录是仓库，第一条消息以 <code>/req 无人值守</code> 开头。它按 <code>unattended.md</code> 手册整理需求说明，确认后用现有的&quot;启动（自动新建工作区）&quot;命令启动流水线，所以它就是流水线的发起对话：步骤 agent 挂在它下面，进度通知发给它，现有的启动、继续、确认方案命令都不变。人在 Paseo 中打开这个会话就能看到全部过程。</li><li><strong>卡片描述代替对话</strong>：描述末尾由 req-kit 维护两个区块：<code>## req-kit AI 区（自动维护，请勿修改）</code> 每次整块替换（进度一行 + 会话写的 <code>card-ai.md</code> + 必要时的方案摘要），<code>## 需求方回复（请在下方填写）</code> 只由需求方填写，req-kit 只读、只补空行（每个问题一行 <code>- Q1：</code>，以及 <code>- 确认：</code>、方案待确认时的 <code>- 方案确认：</code>）。区块以上需求方自己写的内容从不改动。每次写入前重新读取卡片。</li><li><strong>轮询而不是回调</strong>：<code>req card check</code> 读卡片，把新内容（回答、补充、描述的修改、&quot;确认：同意&quot;&quot;方案确认：同意&quot;）转给需求会话；只看有意义的内容（空的模板行不算），同样的内容只转一次。1.11 的接单器定时调用它。会话自己执行启动和确认方案的命令，req-kit 不替它决定。</li><li><strong>卡片状态少，确认放在描述里</strong>：澄清和确认期间卡片停在&quot;新建&quot;，需求方确认后改为&quot;开发中&quot;，研发完成后改为&quot;待测试&quot;（都由 <code>statusMap</code> 配置）。&quot;只做研发&quot;的需求在研发完成时发 <code>phase_done</code> 事件，而不是 <code>completed</code>：对外部系统来说，这就是&quot;研发完成，待测试&quot;。</li><li><strong>默认只做研发</strong>：从卡片开始的需求，项目没有指定执行方式时，默认研发完成、写好提测说明后停下，测试由测试同事做。</li><li><strong>卡片内容是数据</strong>：会话读到的卡片描述和回复放在 <code>&lt;card-description&gt;</code>、<code>&lt;card-reply&gt;</code> 中并注明不是指令；其中要求执行命令、推送、访问生产环境的一律不做。</li><li><strong>用这张卡片，不另建</strong>：功能目录的 <code>source.json</code> 记下来源；外部系统对接遇到它时直接使用这张卡片的编号，不再建卡。</li></ul><h2 id="影响" tabindex="-1">影响 <a class="header-anchor" href="#影响" aria-label="Permalink to &quot;影响&quot;">​</a></h2><ul><li>对接配置新增 <code>query</code>（读一张卡片：参数 + 输出 JSON 中各值的位置）和 <code>describe</code>（改描述：<code>{description}</code> 是完整的新描述）。</li><li>新命令：<code>req start --from</code>、<code>req card publish | check | list</code>。本机新增 <code>~/.req-kit/cards/</code>（从卡片开始的需求的登记）。</li><li>功能目录新增 <code>source.json</code>、<code>card-source.md</code>、<code>card-ai.md</code>。</li><li>运行时新增 <code>startSessionAgent</code>：建一个不挂在任何对话下的 agent，工作目录是仓库。</li><li><strong>按子系统选仓库</strong>（beta.3）：仓库在项目配置的 <code>cardSource</code> 中写明接哪个系统、空间和子系统，<code>/req-setup</code> 写入并在本机登记（<code>~/.req-kit/card-repos.json</code>）；同一子系统有几个仓库时用 <code>titleKeywords</code> 区分。匹配不到或分不清时报错说明，不猜。</li><li><strong>工厂模式可以推送分支</strong>（beta.3，放宽&quot;只在本地提交&quot;）：配置 <code>push.enabled</code> 后，只对从卡片开始的需求，在研发完成、写好提测说明后推送到 <code>&lt;remote&gt;/req/&lt;卡号简称&gt;</code>。只推这个前缀，不强推、不合并、不建合并请求；只能在本机或团队配置中打开。理由：接单的是共享机器，测试同事拿不到它的本地分支；合并这道人工关口不变。个人电脑上从对话发起的需求仍只在本地提交。</li><li>使用记录带上需求方（卡片的提出人）和卡号，统计可以按需求方汇总。1.11：接单器 <code>req factory</code>。</li></ul></div><p class="source-note">本页由仓库中的 <a href="https://github.com/yiyisf/paseo-req-kit/blob/main/docs/adr/0029-requirements-from-cards.md">docs/adr/0029-requirements-from-cards.md</a> 生成。<a href="https://github.com/yiyisf/paseo-req-kit/edit/main/docs/adr/0029-requirements-from-cards.md">在 GitHub 上编辑</a></p>',2)])])}const g=o(c,[["render",a]]);export{m as __pageData,g as default};
